-- =====================================================================
-- Inicialización de catalog_record y catalog_record_value
-- Jerarquía HABILITACION_CAMPOS > SECCIONES_HABILITADAS > ETAPAS_HABILITADAS
-- Origen : catalogos__inicializacion.json, grupo code = 'ANEXO_F_HABILITACION_CAMPOS'
--          5 grupos (nivel 1), 30 secciones (nivel 2) y
--          210 registros de etapa (7 por sección, uno por cada
--          atributo de atributos_extra excepto ubicacion_en_caso_de_uso)
--          Habilitaciones: 'X' = 162, '—' = 43, '-' = 5
-- Dialecto: SQL ANSI (SQL:2003)
-- ---------------------------------------------------------------------
-- Prerrequisitos
--   * catalog contiene los code 'HABILITACION_CAMPOS', 'SECCIONES_HABILITADAS', 'ETAPAS_HABILITADAS', encadenados por parent_id
--     (SECCIONES -> HABILITACION_CAMPOS, ETAPAS -> SECCIONES; Regla 23).
--   * catalog_field define name = 'codigo' y 'nombre' en HABILITACION_CAMPOS y
--     SECCIONES_HABILITADAS, y name = 'etapa' y 'habilitacion' en ETAPAS_HABILITADAS.
--
-- Valores cargados
--   HABILITACION_CAMPOS  : codigo, nombre
--   SECCIONES_HABILITADAS: codigo, nombre
--   ETAPAS_HABILITADAS   : etapa (nombre del atributo, p. ej. '1.1 Perfil'),
--                          habilitacion (valor del atributo tal cual: 'X', '—' o '-')
--   Se crea UN registro de ETAPAS_HABILITADAS POR ATRIBUTO: la restricción
--   uk_record_field (record_id, field_id) impide guardar varias 'etapa' en un
--   mismo registro.
--
-- Mecánica ("id más recientemente generado")
--   SQL ANSI no tiene una función portable para leer el último id generado;
--   se usan subconsultas escalares MAX(id) por catálogo sobre los registros
--   creados en esta carga (id > MAX(id) previo a la carga):
--     * padre de una SECCION: el último grupo HABILITACION_CAMPOS insertado;
--     * padre de una ETAPA  : la última SECCION insertada;
--     * los valores se asignan al registro recién creado de su catálogo.
--   Condición: una sola sesión, sin inserciones concurrentes en
--   catalog_record. Se recomienda ejecutarlo dentro de una única transacción.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Paso 1. Tablas temporales
--   tmp_hab_control : MAX(id) de catalog_record antes de la carga.
--   tmp_hab_item    : jerarquía esperada (nivel, clave, clave del padre,
--                   habilitación), usada para verificar la carga en el paso 5.
--                   La clave es 'codigo' en niveles 1-2 y 'etapa' en el nivel 3.
-- ---------------------------------------------------------------------
CREATE LOCAL TEMPORARY TABLE tmp_hab_control (
    max_record_id_previo BIGINT NOT NULL
) ON COMMIT PRESERVE ROWS;

CREATE LOCAL TEMPORARY TABLE tmp_hab_item (
    orden          INTEGER       NOT NULL PRIMARY KEY,
    nivel          INTEGER       NOT NULL,
    clave          VARCHAR(4000) NOT NULL,
    padre_clave    VARCHAR(4000),
    habilitacion   VARCHAR(4000)
) ON COMMIT PRESERVE ROWS;


-- ---------------------------------------------------------------------
-- Paso 2. Verificación previa — DEBE DEVOLVER 0 FILAS antes de continuar
-- ---------------------------------------------------------------------
SELECT x.code, x.problema
FROM (
    SELECT e.code,
           CASE WHEN c.id IS NULL THEN 'catálogo inexistente'
                WHEN e.code <> 'ETAPAS_HABILITADAS' AND fc.id IS NULL THEN 'falta campo codigo'
                WHEN e.code <> 'ETAPAS_HABILITADAS' AND fn.id IS NULL THEN 'falta campo nombre'
                WHEN e.code =  'ETAPAS_HABILITADAS' AND fe.id IS NULL THEN 'falta campo etapa'
                WHEN e.code =  'ETAPAS_HABILITADAS' AND fh.id IS NULL THEN 'falta campo habilitacion'
                WHEN e.code = 'SECCIONES_HABILITADAS'
                 AND (c.parent_id IS NULL OR c.parent_id <> (SELECT id FROM catalog WHERE code = 'HABILITACION_CAMPOS'))
                     THEN 'parent_id no apunta a HABILITACION_CAMPOS (Regla 23)'
                WHEN e.code = 'ETAPAS_HABILITADAS'
                 AND (c.parent_id IS NULL OR c.parent_id <> (SELECT id FROM catalog WHERE code = 'SECCIONES_HABILITADAS'))
                     THEN 'parent_id no apunta a SECCIONES_HABILITADAS (Regla 23)'
           END AS problema
    FROM (VALUES ('HABILITACION_CAMPOS'), ('SECCIONES_HABILITADAS'), ('ETAPAS_HABILITADAS')) AS e (code)
    LEFT JOIN catalog c        ON c.code = e.code
    LEFT JOIN catalog_field fc ON fc.catalog_id = c.id AND fc.name = 'codigo'
    LEFT JOIN catalog_field fn ON fn.catalog_id = c.id AND fn.name = 'nombre'
    LEFT JOIN catalog_field fe ON fe.catalog_id = c.id AND fe.name = 'etapa'
    LEFT JOIN catalog_field fh ON fh.catalog_id = c.id AND fh.name = 'habilitacion'
) x
WHERE x.problema IS NOT NULL;

-- ---------------------------------------------------------------------
-- Paso 3. Punto de partida de la identidad
-- ---------------------------------------------------------------------
SELECT COALESCE(MAX(id), 0) FROM catalog_record;

-- ---------------------------------------------------------------------
-- Paso 4. Carga, en el orden del JSON
-- ---------------------------------------------------------------------

