-- ---------------------------------------------------------------------
-- Paso 5. Verificación posterior
-- ---------------------------------------------------------------------
-- 5.1 Conteos. Esperado: HABILITACION_CAMPOS 5/10, SECCIONES_HABILITADAS 30/60, ETAPAS_HABILITADAS 210/420
SELECT c.code,
       COUNT(DISTINCT r.id) AS registros,
       COUNT(v.id)          AS valores
FROM catalog c
JOIN catalog_record r            ON r.catalog_id = c.id
LEFT JOIN catalog_record_value v ON v.record_id = r.id
WHERE c.code IN ('HABILITACION_CAMPOS', 'SECCIONES_HABILITADAS', 'ETAPAS_HABILITADAS')
  AND r.id > (SELECT max_record_id_previo FROM tmp_hab_control)
GROUP BY c.code;

-- 5.2 Jerarquía y habilitaciones: compara (nivel, clave, clave del padre,
--     habilitación) cargados contra los esperados, en ambos sentidos.
--     DEBE DEVOLVER 0 FILAS.
WITH cargado (nivel, clave, padre_clave, habilitacion) AS (
    SELECT CASE c.code WHEN 'HABILITACION_CAMPOS' THEN 1 WHEN 'SECCIONES_HABILITADAS' THEN 2 ELSE 3 END,
           vk.valor, vp.valor, vb.valor
    FROM catalog_record rh
    JOIN catalog c               ON c.id = rh.catalog_id AND c.code IN ('HABILITACION_CAMPOS', 'SECCIONES_HABILITADAS', 'ETAPAS_HABILITADAS')
    JOIN catalog_record_value vk ON vk.record_id = rh.id
    JOIN catalog_field fk        ON fk.id = vk.field_id
                                AND fk.name = CASE WHEN c.code = 'ETAPAS_HABILITADAS' THEN 'etapa' ELSE 'codigo' END
    LEFT JOIN (catalog_record_value vp
               JOIN catalog_field fp ON fp.id = vp.field_id AND fp.name = 'codigo')
                                 ON vp.record_id = rh.parent_record_id
    LEFT JOIN (catalog_record_value vb
               JOIN catalog_field fb ON fb.id = vb.field_id AND fb.name = 'habilitacion')
                                 ON vb.record_id = rh.id
    WHERE rh.id > (SELECT max_record_id_previo FROM tmp_hab_control)
),
esperado (nivel, clave, padre_clave, habilitacion) AS (
    SELECT nivel, clave, padre_clave, habilitacion FROM tmp_hab_item
)
SELECT 'falta en la carga' AS diferencia, nivel, clave, padre_clave, habilitacion
FROM (SELECT * FROM esperado EXCEPT ALL SELECT * FROM cargado) f
UNION ALL
SELECT 'sobra en la carga', nivel, clave, padre_clave, habilitacion
FROM (SELECT * FROM cargado EXCEPT ALL SELECT * FROM esperado) s;

-- 5.3 Matriz de habilitación resultante (informativa): una fila por sección.
SELECT vs.valor AS seccion,
       SUM(CASE WHEN vb.valor = 'X' THEN 1 ELSE 0 END) AS etapas_habilitadas,
       COUNT(*)                                          AS etapas_total
FROM catalog_record re
JOIN catalog ce              ON ce.id = re.catalog_id AND ce.code = 'ETAPAS_HABILITADAS'
JOIN catalog_record_value vs ON vs.record_id = re.parent_record_id
JOIN catalog_field fs        ON fs.id = vs.field_id AND fs.name = 'codigo'
JOIN catalog_record_value vb ON vb.record_id = re.id
JOIN catalog_field fb        ON fb.id = vb.field_id AND fb.name = 'habilitacion'
WHERE re.id > (SELECT max_record_id_previo FROM tmp_hab_control)
GROUP BY vs.valor
ORDER BY vs.valor;

-- ---------------------------------------------------------------------
-- Paso 6. Limpieza
-- ---------------------------------------------------------------------
DROP TABLE tmp_hab_item;
DROP TABLE tmp_hab_control;
